import{_ as t,c as a,o as r,ae as o}from"./chunks/framework.Cd-3tpCq.js";const l=JSON.parse('{"title":"GDPR Requests","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/customers/gdpr/index.md","filePath":"api/graphql-api/admin/customers/gdpr/index.md"}'),s={name:"api/graphql-api/admin/customers/gdpr/index.md"};function d(n,e,i,c,u,h){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="gdpr-requests" tabindex="-1">GDPR Requests <a class="header-anchor" href="#gdpr-requests" aria-label="Permalink to &quot;GDPR Requests&quot;">​</a></h1><p>The GDPR Requests menu manages the privacy requests customers raise — to <strong>export</strong> their personal data or to <strong>delete</strong> their account. It is the admin&#39;s queue for reviewing and actioning those requests, plus an ad-hoc data export you can run for any customer. It mirrors the admin <strong>Customers → GDPR Data Request</strong> screen.</p><h2 id="what-a-request-holds" tabindex="-1">What a request holds <a class="header-anchor" href="#what-a-request-holds" aria-label="Permalink to &quot;What a request holds&quot;">​</a></h2><p>A request records the customer (or email), the request <code>type</code> (<code>update</code> or <code>delete</code>), a <code>status</code>, and an optional message. New requests arrive from the storefront; admins move them through the workflow.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>A request&#39;s <code>status</code> moves between: <code>pending</code>, <code>processing</code>, <code>declined</code>, <code>approved</code>, and <code>revoked</code>. <strong>Update</strong> is a plain metadata change — set the status and message as the request is triaged. The destructive action happens through <strong>Process</strong>, not Update.</p><h2 id="process-—-the-explicit-action" tabindex="-1">Process — the explicit action <a class="header-anchor" href="#process-—-the-explicit-action" aria-label="Permalink to &quot;Process — the explicit action&quot;">​</a></h2><p><strong>Process</strong> approves a request and carries out what it asks for:</p><ul><li>For a <strong>delete</strong> request, processing cascades into removing the customer&#39;s account and related data.</li><li>For an <strong>update</strong> request, processing marks it approved; the admin then applies the requested changes through the regular customer update.</li></ul><p>Processing refuses to re-run on a request that is already approved or revoked.</p><h2 id="data-download" tabindex="-1">Data download <a class="header-anchor" href="#data-download" aria-label="Permalink to &quot;Data download&quot;">​</a></h2><p><strong>Download Data Export</strong> is an ad-hoc export — run it for any customer, not tied to a specific request. It returns a structured bundle of the customer&#39;s data (profile, addresses, orders, reviews, wishlist, notes), with sensitive fields such as passwords stripped.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List Requests</a></td><td><code>adminCustomerGdprRequests</code> query</td></tr><tr><td><a href="./detail.html">Request Detail</a></td><td><code>adminCustomerGdprRequest(id:)</code> query</td></tr><tr><td><a href="./update.html">Update Request</a></td><td><code>updateAdminCustomerGdprRequest</code> mutation</td></tr><tr><td><a href="./process.html">Process (Approve + Execute)</a></td><td><code>createAdminCustomerGdprProcess</code> mutation</td></tr><tr><td><a href="./delete.html">Delete Request</a></td><td><code>deleteAdminCustomerGdprRequest</code> mutation</td></tr><tr><td><a href="./download-data.html">Download Data Export</a></td><td><code>createAdminCustomerGdprDownloadData</code> mutation</td></tr></tbody></table><p>Permissions: <code>customers.gdpr_requests.view</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',16)]))}const m=t(s,[["render",d]]);export{l as __pageData,m as default};
